        for (const entry of entries) {
          const file = path.join(dir, entry.name);
          if (entry.isDirectory()) Object.assign(result, await files(file));
          else
            result[file] = {
              content: (await fs.readFile(file)).toString('base64'),
              mtimeMs: (await fs.stat(file)).mtimeMs,
            };
        }
        return result;
      };
