        recoverNativeSdkChecks(root, run, racingRuntime, {
          reconcileInterrupted: true,
          stoppedActions: [
            {
              actionId: action.id,
              attempt: action.attempt,
              inputHash: action.inputHash,
              claimToken: action.claim!.token,
