      projectRoot: f.root,
      name: f.run.runId,
      dryRun: false,
      recover: true,
      confirmed: false,
    });
    expect(again.exitCode).toBe(0);
    expect(again.data).toMatchObject({ alreadyArchived: true, historicalRecovery: true });
    expect((await f.runtime.inspect(f.run.runId)).revision).toBe(completed.revision);
  },
);

