    });
    expect(prepared.state).toMatchObject({ phase: 'build', workflow: 'full' });
    expect(prepared.actions.at(-1)).toMatchObject({
      stepId: 'full.build.execute',
      status: 'pending',
    });
    await f.cli('guard', 'example', 'build', '--apply', '--local', '--', ...buildArgv);
